import type { ComponentPropsWithRef, ReactNode } from 'react';
import { Children } from 'react';
import { cn } from '@/lib/utils';

export type LoaderVariant = 'spinner' | 'dots' | 'bars' | 'ring';
export type LoaderSize = 'xs' | 'sm' | 'md' | 'lg';

const variantClass: Record<LoaderVariant, string> = {
	spinner: 'loading-spinner',
	dots: 'loading-dots',
	bars: 'loading-bars',
	ring: 'loading-ring',
};

const sizeClass: Record<LoaderSize, string> = {
	xs: 'loading-xs',
	sm: 'loading-sm',
	md: 'loading-md',
	lg: 'loading-lg',
};

function hasNode(value: ReactNode) {
	return Children.toArray(value).some((node) => typeof node !== 'string' || node.trim().length > 0);
}

export type LoaderProps = Omit<ComponentPropsWithRef<'span'>, 'children'> & {
	variant?: LoaderVariant;
	size?: LoaderSize;
	label?: string;
	decorative?: boolean;
};

export function Loader({
	variant = 'spinner',
	size = 'sm',
	label = '加载中',
	decorative = false,
	className,
	role,
	'aria-label': ariaLabel,
	'aria-hidden': ariaHidden,
	...props
}: LoaderProps) {
	return (
		<span
			data-slot='loader'
			data-variant={variant}
			data-size={size}
			role={decorative ? undefined : (role ?? 'status')}
			aria-live={decorative ? undefined : 'polite'}
			aria-label={decorative ? undefined : (ariaLabel ?? label)}
			aria-hidden={decorative ? true : ariaHidden}
			className={cn('inline-grid shrink-0 place-items-center align-middle leading-none', className)}
			{...props}
		>
			<span
				aria-hidden='true'
				className={cn('loading motion-reduce:animate-none', variantClass[variant], sizeClass[size])}
			/>
		</span>
	);
}

export type LoadingIndicatorLayout = 'inline' | 'section' | 'page';

export type LoadingIndicatorProps = ComponentPropsWithRef<'div'> & {
	variant?: LoaderVariant;
	size?: LoaderSize;
	layout?: LoadingIndicatorLayout;
	label?: ReactNode;
	description?: ReactNode;
	loaderLabel?: string;
	contentClassName?: string;
};

const layoutClass: Record<LoadingIndicatorLayout, string> = {
	inline: 'inline-flex min-h-0 flex-row items-center gap-2 text-left',
	section: 'flex min-h-40 flex-col items-center justify-center gap-2 text-center',
	page: 'flex min-h-[24rem] flex-col items-center justify-center gap-3 text-center',
};

export function LoadingIndicator({
	variant = 'dots',
	size = 'md',
	layout = 'section',
	label = '正在加载',
	description,
	loaderLabel = '加载中',
	contentClassName,
	className,
	'aria-label': ariaLabel,
	...props
}: LoadingIndicatorProps) {
	const showLabel = hasNode(label);
	const showDescription = hasNode(description);
	return (
		<div
			data-slot='loading-indicator'
			data-layout={layout}
			role='status'
			aria-live='polite'
			aria-busy='true'
			aria-label={ariaLabel ?? (showLabel ? undefined : loaderLabel)}
			className={cn('text-base-content min-w-0', layoutClass[layout], className)}
			{...props}
		>
			<Loader decorative variant={variant} size={size} />
			{showLabel || showDescription ? (
				<div className={cn('min-w-0', layout === 'inline' && 'flex items-baseline gap-2', contentClassName)}>
					{showLabel ? <div className='text-sm font-medium'>{label}</div> : null}
					{showDescription ? <div className='text-base-content/65 text-xs leading-5'>{description}</div> : null}
				</div>
			) : null}
		</div>
	);
}

import type { ComponentPropsWithRef, ReactNode } from 'react';
import { cn } from '@/lib/utils';
import type { LoaderSize, LoaderVariant } from './loader';
import { Loader } from './loader';

export type PendingButtonProps = ComponentPropsWithRef<'button'> & {
	pending?: boolean;
	pendingLabel?: ReactNode;
	pendingAriaLabel?: string;
	loaderVariant?: LoaderVariant;
	loaderSize?: LoaderSize;
};

export function PendingButton({
	pending = false,
	pendingLabel = '处理中',
	pendingAriaLabel,
	loaderVariant = 'spinner',
	loaderSize = 'xs',
	disabled,
	type = 'button',
	children,
	className,
	'aria-label': ariaLabel,
	...props
}: PendingButtonProps) {
	const inferredIdleLabel = typeof children === 'string' || typeof children === 'number' ? String(children) : undefined;
	const inferredPendingLabel =
		typeof pendingLabel === 'string' || typeof pendingLabel === 'number' ? String(pendingLabel) : undefined;
	return (
		<button
			data-slot='pending-button'
			data-pending={pending ? 'true' : 'false'}
			type={type}
			disabled={disabled || pending}
			aria-busy={pending || undefined}
			aria-label={pending ? (pendingAriaLabel ?? inferredPendingLabel ?? ariaLabel) : (ariaLabel ?? inferredIdleLabel)}
			className={cn('btn', className)}
			{...props}
		>
			<span className='grid min-w-0 place-items-center'>
				<span
					aria-hidden={pending || undefined}
					className={cn('col-start-1 row-start-1 inline-flex min-w-0 items-center gap-2', pending && 'invisible')}
				>
					{children}
				</span>
				<span
					aria-hidden={!pending || undefined}
					className={cn('col-start-1 row-start-1 inline-flex min-w-0 items-center gap-2', !pending && 'invisible')}
				>
					<Loader decorative size={loaderSize} variant={loaderVariant} />
					{pendingLabel}
				</span>
			</span>
		</button>
	);
}

import type { ComponentPropsWithRef, ReactNode } from 'react';
import { cn } from '@/lib/utils';
import type { LoaderSize, LoaderVariant } from './loader';
import { LoadingIndicator } from './loader';

export type LoadingOverlayBackdrop = 'subtle' | 'solid' | 'transparent';

export type LoadingOverlayProps = ComponentPropsWithRef<'div'> & {
	active?: boolean;
	label?: ReactNode;
	description?: ReactNode;
	variant?: LoaderVariant;
	size?: LoaderSize;
	backdrop?: LoadingOverlayBackdrop;
	contentClassName?: string;
};

const backdropClass: Record<LoadingOverlayBackdrop, string> = {
	subtle: 'bg-base-100/70 backdrop-blur-[1px]',
	solid: 'bg-base-100',
	transparent: 'bg-transparent',
};

export function LoadingOverlay({
	active = false,
	label = '正在刷新',
	description,
	variant = 'spinner',
	size = 'md',
	backdrop = 'subtle',
	contentClassName,
	children,
	className,
	...props
}: LoadingOverlayProps) {
	return (
		<div
			data-slot='loading-overlay'
			data-active={active ? 'true' : 'false'}
			aria-busy={active || undefined}
			className={cn('relative min-w-0', className)}
			{...props}
		>
			<div
				data-slot='loading-overlay-content'
				inert={active || undefined}
				aria-hidden={active || undefined}
				className={cn('min-w-0', contentClassName)}
			>
				{children}
			</div>
			{active ? (
				<div
					data-slot='loading-overlay-backdrop'
					className={cn('absolute inset-0 z-10 grid place-items-center', backdropClass[backdrop])}
				>
					<LoadingIndicator
						className='bg-base-100/90 rounded-box border-base-300 max-w-[min(90%,24rem)] border px-4 py-3 shadow-sm'
						contentClassName='block'
						layout='inline'
						label={label}
						description={description}
						variant={variant}
						size={size}
					/>
				</div>
			) : null}
		</div>
	);
}

import type { ComponentPropsWithRef } from 'react';
import { cn } from '@/lib/utils';

export type SkeletonShape = 'text' | 'rect' | 'circle';

export type SkeletonProps = Omit<ComponentPropsWithRef<'div'>, 'children'> & {
	shape?: SkeletonShape;
};

const skeletonShapeClass: Record<SkeletonShape, string> = {
	text: 'h-4 w-full rounded-sm',
	rect: 'h-20 w-full rounded-md',
	circle: 'size-10 shrink-0 rounded-full',
};

export function Skeleton({ shape = 'text', className, 'aria-hidden': ariaHidden = true, ...props }: SkeletonProps) {
	return (
		<div
			data-slot='skeleton'
			data-shape={shape}
			aria-hidden={ariaHidden}
			className={cn('skeleton bg-base-300/70 motion-reduce:animate-none', skeletonShapeClass[shape], className)}
			{...props}
		/>
	);
}

export type LoadingRowsVariant = 'list' | 'table';
export type LoadingRowsDensity = 'compact' | 'comfortable';
export type LoadingRowsColumns = 1 | 2 | 3 | 4;

export type LoadingRowsProps = Omit<ComponentPropsWithRef<'div'>, 'children'> & {
	variant?: LoadingRowsVariant;
	density?: LoadingRowsDensity;
	rows?: number;
	columns?: LoadingRowsColumns;
	showHeader?: boolean;
	showLeading?: boolean;
	showTrailing?: boolean;
	label?: string;
};

const tableColumnsClass: Record<LoadingRowsColumns, string> = {
	1: 'grid-cols-1',
	2: 'grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]',
	3: 'grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)_minmax(0,.75fr)]',
	4: 'grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)_minmax(0,.75fr)_minmax(0,.5fr)]',
};

const cellWidthClass = ['w-4/5', 'w-2/3', 'w-3/4', 'w-1/2'] as const;
const rowPaddingClass: Record<LoadingRowsDensity, string> = {
	compact: 'py-2',
	comfortable: 'py-3',
};

function normalizeRows(rows: number) {
	return Number.isFinite(rows) ? Math.min(20, Math.max(1, Math.floor(rows))) : 5;
}

export function LoadingRows({
	variant = 'list',
	density = 'comfortable',
	rows = 5,
	columns = 4,
	showHeader = true,
	showLeading = true,
	showTrailing = true,
	label = '正在加载列表',
	className,
	'aria-label': ariaLabel,
	...props
}: LoadingRowsProps) {
	const rowCount = normalizeRows(rows);
	return (
		<div
			data-slot='loading-rows'
			data-variant={variant}
			data-rows={rowCount}
			role='status'
			aria-live='polite'
			aria-busy='true'
			aria-label={ariaLabel ?? label}
			className={cn('min-w-0', className)}
			{...props}
		>
			<div aria-hidden='true' className='min-w-0'>
				{variant === 'table' && showHeader ? (
					<div className={cn('border-base-300 grid gap-4 border-b px-3 py-2', tableColumnsClass[columns])}>
						{Array.from({ length: columns }, (_, column) => (
							// biome-ignore lint/suspicious/noArrayIndexKey: Deterministic skeleton slots have no state.
							<Skeleton key={`header-${column}`} className={cn('h-3', cellWidthClass[column])} />
						))}
					</div>
				) : null}
				{Array.from({ length: rowCount }, (_, row) =>
					variant === 'table' ? (
						<div
							// biome-ignore lint/suspicious/noArrayIndexKey: Deterministic skeleton rows have no state.
							key={`row-${row}`}
							className={cn(
								'border-base-300 grid items-center gap-4 border-b px-3 last:border-b-0',
								tableColumnsClass[columns],
								rowPaddingClass[density],
							)}
						>
							{Array.from({ length: columns }, (_, column) => (
								// biome-ignore lint/suspicious/noArrayIndexKey: Deterministic skeleton cells have no state.
								<Skeleton key={`cell-${column}`} className={cn('h-3.5', cellWidthClass[(row + column) % 4])} />
							))}
						</div>
					) : (
						<div
							// biome-ignore lint/suspicious/noArrayIndexKey: Deterministic skeleton rows have no state.
							key={`row-${row}`}
							className={cn(
								'border-base-300 flex min-w-0 items-center gap-3 border-b px-3 last:border-b-0',
								rowPaddingClass[density],
							)}
						>
							{showLeading ? <Skeleton className='size-9' shape='circle' /> : null}
							<div className='min-w-0 flex-1 space-y-2'>
								<Skeleton className={cn('h-3.5', row % 2 === 0 ? 'w-3/5' : 'w-2/3')} />
								<Skeleton className={cn('h-3', row % 3 === 0 ? 'w-4/5' : 'w-3/4')} />
							</div>
							{showTrailing ? <Skeleton className='h-3 w-12 shrink-0' /> : null}
						</div>
					),
				)}
			</div>
		</div>
	);
}

export * from './loader';
export * from './loading-overlay';
export * from './pending-button';
export * from './skeleton';
